import pandas as pd
from typing import Dict

def run(inputs: Dict[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Extract the high_ts value from watermark
    high_ts = watermark["high_ts"].iloc[0]

    # Filter events to only those AFTER the watermark (not yet applied)
    cdc_events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Sort events by item_id, event_ts, event_seq to process in order
    cdc_events = cdc_events.sort_values(
        by=["item_id", "event_ts", "event_seq"],
        ascending=[True, True, True]
    ).reset_index(drop=True)

    # Create a dictionary to track the current state
    # Key: item_id, Value: (qty_on_hand, last_event_ts)
    state = {}

    # Initialize state from target_snapshot
    for _, row in target_snapshot.iterrows():
        item_id = row["item_id"]
        state[item_id] = {
            "qty_on_hand": row["qty_on_hand"],
            "last_event_ts": row["last_event_ts"]
        }

    # Apply events in order
    for _, event in cdc_events.iterrows():
        item_id = event["item_id"]
        event_ts = event["event_ts"]
        op = event["op"]
        qty = event["qty"]

        if op == "R":  # Receipt: add to quantity
            if item_id not in state:
                # Item doesn't exist, start from 0
                state[item_id] = {"qty_on_hand": 0, "last_event_ts": event_ts}
            state[item_id]["qty_on_hand"] += qty
            state[item_id]["last_event_ts"] = event_ts

        elif op == "A":  # Adjustment: set absolute quantity
            # Adjustment always sets to absolute value, creates item if missing
            state[item_id] = {"qty_on_hand": qty, "last_event_ts": event_ts}

        elif op == "D":  # Delist: remove item
            if item_id in state:
                del state[item_id]

    # Convert state back to DataFrame
    result_rows = []
    for item_id, item_state in state.items():
        result_rows.append({
            "item_id": item_id,
            "qty_on_hand": item_state["qty_on_hand"],
            "last_event_ts": item_state["last_event_ts"]
        })

    if result_rows:
        new_snapshot = pd.DataFrame(result_rows)
        # Ensure correct dtypes
        new_snapshot = new_snapshot.astype({
            "item_id": "int64",
            "qty_on_hand": "float64",
            "last_event_ts": "datetime64[us]"
        })
        # Sort by item_id for consistency
        new_snapshot = new_snapshot.sort_values("item_id").reset_index(drop=True)
    else:
        # Empty snapshot with correct schema
        new_snapshot = pd.DataFrame({
            "item_id": pd.Series([], dtype="int64"),
            "qty_on_hand": pd.Series([], dtype="float64"),
            "last_event_ts": pd.Series([], dtype="datetime64[us]")
        })

    return {"new_snapshot": new_snapshot}
